class puppet_master
{
        # https repo requires apt-transport-https package already
        # requested in a long generic package list elsewhere.
        apt::source { "passenger":
                comment  => "Passenger (Ruby/Puppet)",
                location => "https://oss-binaries.phusionpassenger.com/apt/passenger",
                release  => $lsbdistcodename,
                repos    => "main",
                # Only accept packages if they have "passenger" in the name.
                pin      => {
                        origin   => "oss-binaries.phusionpassenger.com",
                        priority => "901",
                        packages => "*passenger*",
                },
                key      => {
                        id     => "16378A33A6EF16762922526E561F9B9CAC40B2F7",
                        server => "pgp.mit.edu",
                },
                include  => {
                        src => false,
                        deb => true,
                },
        }

        package { ["libnginx-mod-http-passenger", "passenger"]:
                ensure => installed,
                # Forgot to do this in time: Add a dependency to the repo
                # above to avoid accidentally installing the passenger package
                # from proper Debian first.
        }

        # You don't want the stand-alone daemon to occupy 8140/tcp anymore.
        augeas {
                "puppetmaster-start-nope":
                context => "/files/etc/default/puppet-master",
                changes => "set START no";
        }

        class { "::web":
                sites => [
                        "puppet-master",
                ],
                # Really should be the default..
                php => false,
        }
}

class bitlbee_srv($name, $certname) {
        # Partially copied from sid3windr http://pastebin.com/DsCqn0CY
        apt::source {
                "bitlbee":
                        location => "http://code.bitlbee.org/debian/devel/${lsbdistcodename}/${architecture}/",
                        release => "./",
                        repos => "",
                        include_src => false,
                        key      => {
                                "id"     => "FC7345337B5B29D8DAA1A88E94EEA1F2C7E50436",
                                "server" => "pgp.mit.edu",
                        },
        }

        # TODO(wilmer): Translation from $lsbdistcodename to Debian_x.x if I'm ever sufficiently bored?
        apt::source {
                "jgeboski":
                        location => "http://download.opensuse.org/repositories/home:/jgeboski/Debian_8.0",
                        release => "./",
                        repos => "",
                        include_src => false,
                        key      => {
                                "id"     => "1E7BF737CB8709F0F740625B12C6ADA61C85BB5E",
                                "server" => "pgp.mit.edu",
                        },
        }

        package {
                ["bitlbee", "stunnel4"]:
                        ensure => latest;
                #"bitlbee-facebook", "bitlbee-steam"
        }

        service {
                ["bitlbee", "stunnel4"]:
                        ensure => running,
        }

        exec { "stunnel-reload":
                command => "/etc/init.d/stunnel4 reload",
                refreshonly => true,
                require => Service["stunnel4"],
        }

        letsencrypt::cert { "$certname":
                notify => Exec["stunnel-reload"],
        }

        file { "/etc/bitlbee/bitlbee.conf":
                content => template("bitlbee_srv/bitlbee.conf"),
                mode => 0640,
                owner => "root",
                group => "bitlbee",
                notify => Service["bitlbee"],
                #requires => Package["bitlbee"], # for bitlbee group ... except this feature apparently doesn't exist?
        }

        file { "/etc/bitlbee/motd.txt":
                content => template("bitlbee_srv/motd-${name}.txt"),
        }

        file { "/etc/stunnel/stunnel.conf":
                content => template("bitlbee_srv/stunnel.conf"),
                notify => Exec["stunnel-reload"],
        }

        augeas {
                "stunnel-start":
                context => "/files/etc/default/stunnel4",
                changes => "set ENABLED 1",
        }
}

